"""Simulation environments made of an arbitrary USD scene + a robot (generated by tools/create_usd_task.py).

A generated task keeps everything robot-specific (robot, cameras, observations, actions, DDS) from the robot's
reference task (e.g. Isaac-PickPlace-Cylinder-R1D-Dex1-Joint) and replaces the scene with the USD scene of a
SPEC dict (tasks/common_scene/usd_scene_<name>.py). The scene is simulated as it is (its own rigid bodies,
doors, ...); the task has no task object, success or failure condition.

SPEC keys:
    scene_usd     wrapper layer of the copied scene, relative to the project root
    scene_scale   [s, s, s] or None (USD units -> metres); scene_rot [x, y, z, w] (Y-up -> Z-up)
    ground        add a ground plane (the scene has no floor collider)
    dome_light    dome light intensity (0: the scene's own lights only)
    robots        {robot key: {"pos": [x, y, z], "yaw_deg": yaw, "joint_pos": {...}}}  <- robot standing pose
"""

from __future__ import annotations

import math
import os

import torch

import isaaclab.envs.mdp as base_mdp
import isaaclab.sim as sim_utils
from isaaclab.assets import AssetBaseCfg
from isaaclab.scene import InteractiveSceneCfg
from isaaclab.sensors import CameraCfg
from isaaclab.utils import configclass

PROJECT_ROOT = os.environ.get("PROJECT_ROOT") or os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
SCENE_PRIM = "/World/envs/env_.*/Scene"
# entities taken over from the robot's reference task scene
ROBOT_ENTITIES = ("robot", "front_camera", "front_right_camera", "left_wrist_camera", "right_wrist_camera")


@configclass
class UsdTaskSceneCfg(InteractiveSceneCfg):
    """Scene of a generated task; its entities are added by build_scene()."""


def yaw_quat(yaw_deg: float):
    y = math.radians(yaw_deg)
    return (0.0, 0.0, math.sin(y / 2), math.cos(y / 2))


def look_at_quat(eye, target):
    """Orientation (x, y, z, w; 'world' camera convention: x forward, z up) looking from eye to target."""
    dx, dy, dz = (t - e for t, e in zip(target, eye))
    yaw = math.atan2(dy, dx)
    pitch = -math.atan2(dz, math.hypot(dx, dy))
    cy, sy, cp, sp = math.cos(yaw / 2), math.sin(yaw / 2), math.cos(pitch / 2), math.sin(pitch / 2)
    return (-sy * sp, cy * sp, sy * cp, cy * cp)


def overview_camera_pose(pos, yaw_deg):
    """Overview camera behind-left of the robot, looking over its shoulder."""
    y = math.radians(yaw_deg)
    f, l = (math.cos(y), math.sin(y)), (-math.sin(y), math.cos(y))
    eye = (pos[0] - 1.6 * f[0] + 1.0 * l[0], pos[1] - 1.6 * f[1] + 1.0 * l[1], 1.8)
    target = (pos[0] + 0.6 * f[0], pos[1] + 0.6 * f[1], 0.8)
    return eye, target


def build_scene(spec: dict, robot_scene, robot_pose) -> UsdTaskSceneCfg:
    """Scene cfg: the USD scene and the robot + cameras of ``robot_scene``."""
    sc = UsdTaskSceneCfg(num_envs=1, env_spacing=2.5, replicate_physics=True)
    sc.scene = AssetBaseCfg(
        prim_path=SCENE_PRIM,
        init_state=AssetBaseCfg.InitialStateCfg(pos=(0.0, 0.0, 0.0), rot=tuple(spec.get("scene_rot") or (0, 0, 0, 1))),
        spawn=sim_utils.UsdFileCfg(usd_path=os.path.join(PROJECT_ROOT, spec["scene_usd"]),
                                   scale=tuple(spec["scene_scale"]) if spec.get("scene_scale") else None),
    )
    if spec.get("ground"):
        sc.ground = AssetBaseCfg(prim_path="/World/GroundPlane", spawn=sim_utils.GroundPlaneCfg())
    if spec.get("dome_light", 0) > 0:
        sc.light = AssetBaseCfg(prim_path="/World/light",
                                spawn=sim_utils.DomeLightCfg(color=(0.75, 0.75, 0.75), intensity=float(spec["dome_light"])))
    for name in ROBOT_ENTITIES:
        value = getattr(robot_scene, name, None)
        if value is not None:
            setattr(sc, name, value)
    # overview camera; sim_main turns it into a viewport-only camera (Cameras -> PerspectiveCamera)
    eye, target = overview_camera_pose(*robot_pose)
    sc.world_camera = CameraCfg(
        prim_path="/World/PerspectiveCamera", update_period=0.02, height=480, width=640, data_types=["rgb"],
        spawn=sim_utils.PinholeCameraCfg(focal_length=16.5, horizontal_aperture=20.955, clipping_range=(0.05, 1.0e5)),
        offset=CameraCfg.OffsetCfg(pos=eye, rot=look_at_quat(eye, target), convention="world"),
    )
    return sc


def apply_usd_task(env_cfg, spec: dict, robot_key: str) -> None:
    """Turn a robot's reference task cfg (after its __post_init__) into the USD scene + robot environment."""
    from tasks.common_event.event_manager import SimpleEvent

    r = spec["robots"][robot_key]
    pos, yaw = list(r["pos"]), float(r.get("yaw_deg", 0.0))
    scene = build_scene(spec, env_cfg.scene, (pos, yaw))
    init = scene.robot.init_state
    scene.robot = scene.robot.replace(init_state=init.replace(
        pos=tuple(pos), rot=yaw_quat(yaw), joint_pos={**init.joint_pos, **(r.get("joint_pos") or {})}))
    env_cfg.scene = scene

    # no task object: drop the reference task's object terms
    for group, names in ((env_cfg.terminations, ("success",)), (env_cfg.rewards, ("reward",)),
                         (env_cfg.events, ("reset_object",))):
        for n in names:
            if hasattr(group, n):
                setattr(group, n, None)
    if getattr(env_cfg, "event_manager", None) is not None:
        # DDS "reset object" command: nothing to reset; "reset all" resets the robot (and the scene) as before
        env_cfg.event_manager.register("reset_object_self", SimpleEvent(func=lambda env: None))
        env_cfg.event_manager.register("reset_all_self", SimpleEvent(
            func=lambda env: base_mdp.reset_scene_to_default(env, torch.arange(env.num_envs, device=str(env.device)))))
